public class TimestampHostedService : IHostedService, IAsyncDisposable
{
    private readonly ILogger<TimestampHostedService> _logger;
    private Timer? _timer;

    public TimestampHostedService(ILogger<TimestampHostedService> logger)
    {
        _logger = logger;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("Timestamp service starting");
        _timer = new Timer(DoWork, null, TimeSpan.Zero, TimeSpan.FromSeconds(5));
        return Task.CompletedTask;
    }

    private void DoWork(object? state)
    {
        _logger.LogInformation("Current timestamp: {Time}", DateTimeOffset.Now);
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("Timestamp service stopping");
        _timer?.Change(Timeout.Infinite, 0);
        await Task.Delay(500, cancellationToken);
        _timer?.Dispose();
    }

    public async ValueTask DisposeAsync()
    {
        await Task.CompletedTask;
    }
}

